 function watch(job:Job,projectId:string,baseRevisionId:string){if(selectedProjectId.current!==projectId||activeRevisionId.current!==baseRevisionId)return;setJobs(old=>[job,...old.filter(item=>item.id!==job.id)]);if(job.status==='completed'){if(!job.result?.id||!job.result.url||(job.result as Candidate&{baseRevisionId?:string}).baseRevisionId!==baseRevisionId){setError('The job completed without a previewable result.');setBusy(false);return}previewResume.current={time:job.result.sourceFrames?0:(job.result.start??start),playing:false};setTime(job.result.sourceFrames?0:(job.result.start??start));setCandidate(job.result);setRepairTarget(null);setProtectedAreas([]);setView('candidate');setBusy(false);setMessage('Candidate ready. Compare playback before applying.');return}if(['failed','unknown','canceled','cancelled'].includes(job.status)){setError(job.error||'The job could not complete. Your current revision is unchanged.');setMessage('Stopped. Your current video is unchanged. Retry the correction or start another edit.');setBusy(false);return}setMessage(`${job.status==='queued'?'Queued':'Processing'} · your current revision is safe`);poll.current=setTimeout(()=>api<Job>(`/api/jobs/${job.id}`).then(next=>watch(next,projectId,baseRevisionId)).catch(e=>{if(selectedProjectId.current!==projectId||activeRevisionId.current!==baseRevisionId)return;setError(e.message);setBusy(false)}),1500)}
