 async function prepareGenerationPlan(){if(!valid||!project||!prompt.trim())return;const target=project;await run(async()=>{repairMasks(mode,scope,start,end,duration,fps,masks);const a=start,b=end;const body={text:prompt,intent:mode==='audio'?'generate_audio':mode,start:a,end:b,baseRevisionId:target.activeRevisionId,quality:'standard'};const signature=JSON.stringify(body);if(generationRequest.current?.signature!==signature)generationRequest.current={signature,key:crypto.randomUUID()};const result=await api<{plans:ConversationPlan[],requestedPlanId?:string}>(`/api/projects/${target.id}/conversation`,{...body,idempotencyKey:generationRequest.current.key});if(selectedProjectId.current!==target.id)return;const plan=result.plans.find(p=>p.id===result.requestedPlanId);if(!plan)throw Error('No reviewable plan was returned.');generationRequest.current=null;setFocusPlanId(plan.id);setPlanRefresh(v=>v+1);setEditorOpen(false);setDrawing(false);setMessage('Review the affected range, uploaded context and price before running the edit.');});}
