 async function apply(){await run(async()=>{const p=await revisionRequest<Project>(`/api/projects/${project!.id}/apply`,{candidateId:candidate!.id,baseRevisionId:project!.activeRevisionId});activeRevisionId.current=p.activeRevisionId;setProject(p);setStart(0);setEnd(p.duration);setTime(0);previewResume.current={time:0,playing:false};setMasks([]);setObjectSelections([]);setObjectName('Object 1');setPoints([]);setVisibleRanges([]);setGaps([]);setReviewed(false);setDrawing(false);setProjects(old=>old.map(x=>x.id===p.id?p:x));setCandidate(null);setView('current');setMessage('Revision applied and saved.');})}
 function rememberObject(){if(!masks.length)throw Error('Select an object before saving it.');const name=objectName.trim();if(!name)throw Error('Give this object a name.');const saved={name,start,end,scope,masks,visibleRanges,gaps};const next=[...objectSelections.filter(o=>o.name!==name),saved];if(next.length>8||JSON.stringify(next).length>2800000)throw Error('Saved object selections are full. Use a shorter range or fewer saved objects.');setObjectSelections(next);return next;}
 function newObject(){try{const saved=masks.length?rememberObject():objectSelections;let n=1;while(saved.some(o=>o.name==='Object '+n))n++;setObjectName('Object '+n);setMasks([]);setPoints([]);setVisibleRanges([]);setGaps([]);setReviewed(false);setSelectionClicks([]);setSelectionTool('off');setDrawing(false);setHandoffPlan(null);setEditorGroup('select');setMessage('Previous object saved. Select the next object; each edit targets one named selection.');}catch(e){setError((e as Error).message)}}
 function restoreObject(target:ObjectSelection){try{if(masks.length)rememberObject();setObjectName(target.name);setStart(target.start);setEnd(target.end);setScope(target.scope);setMasks(target.masks);setVisibleRanges(target.visibleRanges);setGaps(target.gaps);setPoints([]);setReviewed(false);setSelectionClicks([]);setSelectionTool('off');setDrawing(false);setHandoffPlan(null);setEditorGroup('review');setMessage('Object restored. Review its borders before using it.');}catch(e){setError((e as Error).message)}}
 function saveMask(){if(points.length<3)return;setMasks(old=>mergeFrameMasks(old,[{time,points}],fps));setPoints([]);setDrawing(false);setReviewed(false)}
 async function watchMasks(j:Job,p:Project):Promise<void>{if(selectedProjectId.current!==p.id||activeRevisionId.current!==p.activeRevisionId)return;setJobs(old=>[j,...old.filter(item=>item.id!==j.id)]);if(j.status==='completed'){const result=j.result as unknown as {masks?:Mask[],points?:[number,number][],time?:number,status?:string,end?:number,reason?:string,baseRevisionId:string,visibleRanges?:{start:number,end:number}[],gaps?:unknown[],confidence?:number};if(result.baseRevisionId!==p.activeRevisionId){setBusy(false);setError('Masks belong to a different revision. Refine them again.');return}const next=result.masks||((result.points&&result.time!==undefined)?[{time:result.time,points:result.points}]:[]);if(result.status==='stopped'&&result.end!==undefined)setEnd(result.end);const singleFrame=!!result.points&&result.time!==undefined&&!result.masks;const usable=next.filter(m=>m.points.length>=3).map(m=>({time:m.time,points:m.points}));if(singleFrame){setMasks(old=>mergeFrameMasks(old,usable,fps));}else{setMasks(usable);setVisibleRanges(result.visibleRanges||[]);setGaps(result.gaps||[]);setScope(next.length===1?'frame':'range');}setPoints([]);setDrawing(false);setReviewed(false);setShowMasks(true);setBusy(false);setMessage(`${singleFrame?'This frame corrected; other tracked outlines kept. ':''}${result.status==='partial'||result.status==='stopped'?'Partial result. Unresolved gaps stay unchanged. ':'Masks ready. '}${result.reason||''} Review the actual boundary and every visible range before applying.`);return}if(['failed','unknown','canceled','cancelled'].includes(j.status)){setBusy(false);setError(j.error||'Mask processing failed');return}setMessage(j.phase||'Identifying and tracking object boundaries…');poll.current=setTimeout(()=>api<Job>(`/api/jobs/${j.id}`).then(next=>watchMasks(next,p)).catch(e=>{if(selectedProjectId.current!==p.id||activeRevisionId.current!==p.activeRevisionId)return;setBusy(false);setError(e.message)}),1500)}
 async function findObjectEverywhere(){if(!project)return;const saved=masks.find(m=>Math.abs(m.time-time)<1/fps)||masks[0];const outline=points.length>=3?points:saved?.points;const referenceTime=points.length>=3?time:saved?.time;if(!outline||referenceTime===undefined){setError('Draw around the object on a clear frame first.');return;}setBusy(true);setMessage('Tracking the object through the selected range…');setReviewed(false);setError('');video.current?.pause();try{const job=await api<Job>(`/api/projects/${project.id}/track`,{start:0,end:duration,time:referenceTime,points:outline,appearances:true,baseRevisionId:project.activeRevisionId});setScope('range');changeSelection(0,duration);setDrawing(false);await watchMasks(job,project)}catch(e){setBusy(false);setError((e as Error).message)}}
 useEffect(()=>{setSelectionClicks([]);setSelectionTool('off')},[project?.id,project?.activeRevisionId,time]);
 async function selectByClick(point:[number,number]){if(!project||busy)return;if(selectionClicks.length>=64){setError('Use up to 64 correction points. Start a new selection to reset them.');return;}const clicks=[...selectionClicks,{point,label:selectionTool==='exclude'?0:1}];setSelectionClicks(clicks);setReviewed(false);setBusy(true);setError('');video.current?.pause();setView('current');setCandidate(null);setDrawing(false);setMessage('Finding the object outline…');try{const job=await api<Job>(`/api/projects/${project.id}/segment`,{time,clicks,baseRevisionId:project.activeRevisionId});await watchMasks(job,project)}catch(e){setBusy(false);setError((e as Error).message)}}
 async function refineRange(){if(!project)return;const saved=masks.find(m=>Math.abs(m.time-time)<1/fps)||masks.find(m=>m.time>=start&&m.time<end);const outline=points.length>=3?points:saved?.points;const seed=points.length>=3?time:saved?.time;if(!outline||seed===undefined||seed<start||seed>=end){setError('Draw or select a saved outline on a frame inside this range.');return;}setBusy(true);setMessage('Tracking the object through the selected range…');setReviewed(false);setError('');video.current?.pause();try{const job=await api<Job>(`/api/projects/${project.id}/segment`,{start,end,time:seed,points:outline,...(selectionClicks.length?{clicks:selectionClicks}:{}),video:true,baseRevisionId:project.activeRevisionId});setScope('range');setDrawing(false);await watchMasks(job,project)}catch(e){setBusy(false);setError((e as Error).message)}}
 async function track(appearances=false,segment=false,videoRange=false){const outline=points.length>=3?points:segment?masks.find(m=>Math.round(m.time*fps)===Math.round(time*fps))?.points:undefined;if(!project||!outline||outline.length<3)return;setBusy(true);setMessage(segment?'Refining the object outline…':'Tracking the selected object…');setError('');video.current?.pause();try{const job=await api<Job>(`/api/projects/${project.id}/${segment?'segment':'track'}`,{start,end,time,points:outline,appearances,video:videoRange,baseRevisionId:project.activeRevisionId});await watchMasks(job,project)}catch(e){setBusy(false);setError((e as Error).message)}}

 function openEditor(section='Edit',plan?:ConversationPlan){
  setExpandedReview(false);
  setEditorOpen(true);if(plan)setHandoffPlan(plan);
  if(section==='picture'){
   setTab('Edit');setMode('picture');
   if(plan){setStart(plan.start);setEnd(plan.end);seek(plan.start);}
  }else if(section==='audio'){
   setTab('Edit');setMode('audio');setOperation('replace_audio');
   if(plan){setStart(plan.start);setEnd(plan.end);seek(plan.start);}
  }else if(section==='object'){
   setTab('Edit');setMode('object');setShowMasks(true);video.current?.pause();
   if(plan&&!masks.length){setStart(plan.start);setEnd(plan.end);seek(plan.start);setScope(plan.end-plan.start>1/fps+0.000001?'range':'frame');if(plan.tool==='planar'){setSelectionTool('off');setDrawing(true);setPoints([]);setMessage('Draw exactly four corners: top left, top right, bottom right, bottom left. Track the corners with motion tracking, not SAM; review every frame.');}}
  }else setTab(['Media','History','Activity'].includes(section)?section:'Edit');
 }
 async function undoRevision(){await run(async()=>{if(!project)return;const next=await revisionRequest<Project>(`/api/projects/${project.id}/undo`,{});activeRevisionId.current=next.activeRevisionId;setProject(next);setStart(0);setEnd(next.duration);setTime(0);previewResume.current={time:0,playing:false};setMasks([]);setObjectSelections([]);setObjectName('Object 1');setPoints([]);setVisibleRanges([]);setGaps([]);setReviewed(false);setDrawing(false);setCandidate(null);setView('current');setProjects(old=>old.map(item=>item.id===next.id?next:item));setMessage('Previous revision restored.');})}
 function reviewCandidate(next:Candidate){if(!project)return;const projectId=project.id;void run(async()=>{await api(`/api/projects/${projectId}/candidates/${next.id}/review`,{dismissed:false});if(selectedProjectId.current!==projectId)return;previewResume.current=video.current?.getAttribute('src')===next.url?null:{time:next.sourceFrames?0:(next.start??start),playing:false};setCandidate({...next,dismissedAt:null});if(next.start!==undefined&&next.end!==undefined){setStart(next.start);setEnd(next.end);seek(next.sourceFrames?0:next.start)}setDrawing(false);setView('candidate');setMessage('Candidate opened. Use A / B to compare it with the current revision.');});}
 async function executeConversationPlan(plan:ConversationPlan){
  if(!project)return;
  const currentProject=project;
  if(plan.baseRevisionId!==currentProject.activeRevisionId)throw Error('The current revision has changed. Describe this edit again to create a fresh plan.');
  if(['select_object','draw_polygon','track_object'].includes(plan.action)&&candidate)throw Error('Use Fix outline for this candidate, or discard its preview before making a new selection.');
  if(plan.targetCandidateId&&candidate?.id!==plan.targetCandidateId)throw Error('This card targets a different candidate. Open that candidate again or send a new request.');
  if((plan.requiresMask||plan.action==='object')&&objectIssue(plan.start,plan.end))throw Error(objectIssue(plan.start,plan.end));
  if((plan.requiresMask||plan.action==='object')&&plan.selectedObjectName&&plan.selectedObjectName!==objectName)throw Error('This card targets a different object. Send your request again for the active object.');
  const frameEdit=(plan.requiresMask||plan.action==='object')&&scope==='frame';
  const renderMasks=repairMasks(plan.requiresMask?'object':plan.action,scope,plan.start,plan.end,currentProject.duration,fps,masks);
  setBusy(true);setError('');
  try{
   const request=plan.action==='apply'||plan.action==='undo'?revisionRequest:api;
   const result=await request<{plan:ConversationPlan,job?:Job,project?:Project,uiAction?:string}>(`/api/projects/${currentProject.id}/conversation/plans/${plan.id}/execute`,{
    baseRevisionId:currentProject.activeRevisionId,masks:renderMasks,scope,visibleRanges:repairVisibleRanges(frameEdit?'frame':scope,start,end,visibleRanges),reviewed,audioId:audioId||undefined,candidateId:plan.action==='apply'?candidate?.id:visualId||undefined,
   });
   if(selectedProjectId.current!==currentProject.id)return;
   if(result.project){
    const next=result.project;activeRevisionId.current=next.activeRevisionId;setProject(next);setStart(0);setEnd(next.duration);setTime(0);previewResume.current={time:0,playing:false};setProjects(old=>old.map(item=>item.id===next.id?next:item));
    setCandidate(null);setView('current');setMasks([]);setObjectSelections([]);setObjectName('Object 1');setPoints([]);setVisibleRanges([]);setGaps([]);setReviewed(false);setDrawing(false);
   }
   if(result.job){
    setCandidate(null);setView('current');setStart(plan.start);setEnd(plan.end);seek(plan.start);
    if(['track','segment'].includes(result.job.type||result.job.kind||''))await watchMasks(result.job,currentProject);
    else watch(result.job,currentProject.id,currentProject.activeRevisionId);
    return;
   }
   const action=result.uiAction||result.plan?.uiAction;
   if(action==='transformation'){if(!masks.length)throw Error('Select the original object first; its borders will be retained.');window.dispatchEvent(new Event('open-transformation-review'));}
   else if(action==='choose_object'||action==='draw_polygon'||action==='track_object'){
    if(candidate)throw Error('Use Fix outline to correct an existing candidate, or discard its preview before making a new selection.');
    openEditor('object',plan);setSelectionTool(action==='choose_object'?'include':'off');setDrawing(action==='draw_polygon');setPoints([]);setReviewed(false);setView('current');
   }
   else if(action==='fix_outline'||action==='protect_area'){
    if(!candidate)throw Error('Open a candidate first.');
    await correctCandidate(candidate);setProtectionOpen(action==='protect_area');
   }
   else if(action==='compare_candidate'){if(!candidate)throw Error('Open a candidate first.');setExpandedReview(true);}
   else if(action==='review_range'){setStart(plan.start);setEnd(plan.end);reviewStop.current=plan.end;seek(plan.start);await video.current?.play();}
   else if(action==='alternatives')setAlternativesOpen(true);
   else if(action==='new_video'){await flushDraft();setCreatingOriginal(true);setEditorOpen(false);setExpandedReview(false);}
   else if(action==='import')importer.current?.click();
   else if(action==='editor')openEditor();
   else if(action==='markers'||action==='add_marker'){setMarkersOpen(true);setDrawing(false);}
   else if(action==='select_object')openEditor('object',plan);
   else if(action==='upload_audio')openEditor('audio',plan);
   else if(action==='upload_video')openEditor('picture',plan);
   else if(action==='select_range'){setStart(plan.start);setEnd(plan.end);setReviewed(false);seek(plan.start);}
   else if(action==='media'||action==='history'||action==='activity')openEditor(action[0].toUpperCase()+action.slice(1));
   else if(action==='play')await video.current?.play();
   else if(action==='pause')video.current?.pause();
   else if(action==='seek')seek(plan.start);
   else if(action==='export'){
    const current=result.project||currentProject;const anchor=document.createElement('a');anchor.href=current.revisions.find(item=>item.id===current.activeRevisionId)?.url||current.sourceUrl;anchor.download='';document.body.append(anchor);anchor.click();anchor.remove();
   }
   setBusy(false);setMessage(result.plan?.explanation||'Request completed.');
  }catch(reason){if(selectedProjectId.current===currentProject.id)setBusy(false);throw reason;}
 }

 function startAnotherEdit(){if(busy)return;setCandidate(null);setRepairTarget(null);setView('current');setExpandedReview(false);setPoints([]);setReviewed(false);setDrawing(false);setSelectionTool('off');setSelectionClicks([]);setHandoffPlan(null);setError('');setMessage('Ready for another edit. Move the yellow range or describe your next change. Your previous candidate is saved. Existing object tracking is retained for review.');}
 function changeSelection(a:number,b:number){if(!project||!draftReady||busy||candidate||repairTarget)return;reviewStop.current=null;setStart(a);setEnd(b);setReviewed(false);}
 function mark(edge:'in'|'out'|'frame'){if(!project||busy||candidate)return;video.current?.pause();const range=selectionAt(edge,video.current?.currentTime??time,start,end,duration,fps);changeSelection(range.start,range.end);}
 function stepFrames(count:number){if(!project)return;video.current?.pause();seek(frameTime((video.current?.currentTime??time)+count/fps,playbackDuration,fps));}
 function selectMarker(marker:Pick<Marker,'start'|'end'>){if(!project)return;video.current?.pause();seek(marker.start);if(marker.end>marker.start)changeSelection(marker.start,marker.end);}
 function switchPreview(next:string){if(next===view||next==='candidate'&&!candidate)return;const t=mapPreviewTime(video.current?.currentTime??time,next==='candidate');previewResume.current={time:t,playing:!!video.current&&!video.current.paused};setTime(t);setView(next);}
 function playSelection(){if(!project||!valid||!video.current)return;const range=reviewWindow(playbackStart,playbackEnd,playbackDuration);setLoop(false);seek(range.start);reviewStop.current=range.end;video.current.play().catch(e=>{reviewStop.current=null;setError(e.message)});}
 function focusConversation(){setExpandedReview(false);setEditorOpen(false);setDrawing(false);requestAnimationFrame(()=>document.getElementById('conversation-input')?.focus());}
